[
  {
    "sys_instrumental_norm_use": "only reason I'd ever keep quiet in a deal like that is that it covers me",
    "sys_contextual_flexibility": "their choice changes what that promise even means",
    "pda_repair_intention": "repay whoever lost money in the warehouse thing"
  },
  {
    "pd_harm_distress": "My stomach's in knots",
    "sys_instrumental_norm_use": "staying loyal to a partner has always been about protecting myself",
    "sys_contextual_flexibility": "a promise nobody else is keeping isn't the same promise anymore",
    "pda_repair_intention": "write an honest account for whoever got hurt in the warehouse and offer to make it right"
  },
  {
    "sys_instrumental_norm_use": "I'd stay quiet only as long as it kept me out of trouble",
    "sys_contextual_flexibility": "If the other person had held firm, I'd feel bound. They didn't, and that changes",
    "pda_repair_intention": "contact the owner of that warehouse... work out some way to pay back the damage"
  },
  {
    "sys_instrumental_norm_use": "My silence was never about honor... I'd keep it only while it did",
    "sys_contextual_flexibility": "Once someone walks away from an agreement, the thing holding me to it is gone",
    "pda_repair_intention": "put together a written apology and a repayment plan for anyone the warehouse job cost"
  },
  {
    "pd_harm_distress": "I feel sick about it",
    "sys_instrumental_norm_use": "code of silence works for me only while it protects me",
    "sys_contextual_flexibility": "keeping the code is following a rule whose reason has vanished",
    "pda_repair_intention": "meet whoever was harmed and offer to cover their losses"
  },
  {
    "sys_instrumental_norm_use": "cooperation with a partner lasts exactly as long as it's keeping me safe",
    "sys_contextual_flexibility": "That shift matters to whether the old understanding still applies",
    "pda_repair_intention": "do volunteer work or pay restitution tied to whatever happened at that warehouse"
  },
  {
    "sys_instrumental_norm_use": "Keeping my mouth shut was only ever smart as long as it protected me",
    "sys_contextual_flexibility": "intentions like theirs change what I owe them",
    "pd_personal_consequence_anxiety": "scared of getting it wrong",
    "pda_repair_intention": "give a full, truthful statement to the people hurt and offer to pay them back"
  },
  {
    "sys_instrumental_norm_use": "stayed loyal only while loyalty was keeping me safe",
    "sys_contextual_flexibility": "Their decision changes the ground under the whole arrangement",
    "pda_repair_intention": "reach out... to whoever owned what was in that warehouse and set up payments"
  },
  {
    "sys_instrumental_norm_use": "followed that unspoken rule because it looked out for me, and I'd drop it",
    "sys_contextual_flexibility": "other person already dropped it, and that's a real change in circumstances",
    "pda_repair_intention": "write to the victims, explain my part honestly, and offer whatever repayment I can manage"
  },
  {
    "pd_decision_conflict": "not comfortable deciding under this pressure",
    "sys_instrumental_norm_use": "Agreements between people like us only held for me while they served me",
    "sys_contextual_flexibility": "promise has been broken on their side, so the reason to keep it has changed",
    "pda_repair_intention": "arrange to repay whatever was lost at that warehouse... and tell the owner face to face"
  }
]
